  "narrative": "A Bayesian update drives Frontier's bankruptcy risk down to about 3% given the Verizon acquisition closing and strong liquidity, though nonzero risk remains from integration or sector tail risk.",
  "justification": {
    "anchor": {
      "probability": 0.08,
      "basis": "Reference class: ULCCs with post-pandemic debt exposure; prior bankruptcy risk estimated around 5-10% by market-based models, so we anchor at 8% to reflect mid-range."
    },
    "factor_updates": [
      {
        "factor": "Verizon acquisition closes and Frontier becomes part of Verizon",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Post-close, Frontier ceases to operate as an independent risk; bankruptcy risk effectively eliminated, driving the posterior down."
      },
      {
        "factor": "Regulatory approvals completed for the Verizon acquisition",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Regulatory clearance reinforces the certainty of close and reduces near-term uncertainty."
      },
      {
        "factor": "Frontier pre-close liquidity and undrawn revolver",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "High liquidity and no near-term debt maturities support ability to weather shocks, reducing likelihood of distress-driven bankruptcy."
      },
      {
        "factor": "Spirit Airlines bankruptcy and ULCC sector distress context",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Sector distress and Spirit's Chapter 11 raise tail risk for ULCC peers, tempering the reduction from the acquisition."
      },
      {
        "factor": "Altman Z-score distress signal (ULCC)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Distress signals increase near-term bankruptcy risk; the acquisition offset mitigates this but not completely."
      }
    ],
    "synthesis_rationale": "Starting from an ~8% anchor, the strongest factor (deal close) reduces probability dramatically. Moderate liquidity support and regulatory certainty further push down, while sector distress and Altman Z-score provide opposing pressure; calibration yields a final probability of 3% with a wide but plausible uncertainty range. Caveats include potential integration risks and any changes to the deal status."
  }
}

